from django.db import connection


def provision():
    # SQL fixtures represent tables owned by an external application.
    with connection.cursor() as cursor:
        cursor.execute('CREATE SCHEMA IF NOT EXISTS "example_legacy_docs"')
        cursor.execute('CREATE SCHEMA IF NOT EXISTS "example_legacy_rows"')
        cursor.execute(
            'CREATE TABLE IF NOT EXISTS "example_legacy_docs"."record" ('
            "id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "
            "filename varchar(100) NOT NULL)"
        )
        cursor.execute(
            'CREATE TABLE IF NOT EXISTS "example_legacy_rows"."record" ('
            "id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "
            'document_id bigint NOT NULL REFERENCES "example_legacy_docs"."record" '
            "DEFERRABLE INITIALLY DEFERRED, reference varchar(100) NOT NULL)"
        )


def remove():
    # Test fixtures own these objects in Django's disposable test database.
    with connection.cursor() as cursor:
        cursor.execute('DROP TABLE IF EXISTS "example_legacy_rows"."record"')
        cursor.execute('DROP TABLE IF EXISTS "example_legacy_docs"."record"')
        cursor.execute('DROP SCHEMA IF EXISTS "example_legacy_rows"')
        cursor.execute('DROP SCHEMA IF EXISTS "example_legacy_docs"')
